package net.officefloor.hq.app.people;

import java.util.List;

/**
 * A person as the API returns it; patrons are referenced by id. thrust is alpha times beta, or null
 * (n/a) when either is blank. momentum is thrust plus three times (gamma minus alpha), or null (n/a)
 * when thrust or gamma is. scaled is momentum times two, and third is scaled divided by three (rounded
 * to the nearest, see {@link SheetMath#divide}); both null (n/a) when momentum is. norm is scaled minus the
 * sheet's average scaled (over the people whose scaled is not n/a, rounded like every divide), null
 * (n/a) when scaled is. backing is the momentum of each patron added up (n/a patrons add nothing), null
 * (n/a) when the person's own momentum is. quarter is scaled divided by four (rounded like every divide)
 * and tier is SINK when scaled is below zero, STEADY from 0 up to 199 and SURGE at 200 or more; both
 * null (n/a) when scaled is. keel is scaled plus momentum, null (n/a) when momentum is.
 * fathom is keel plus momentum and draft is keel plus thrust; both null (n/a) when keel is.
 */
public record PersonView(Long id, String name, Integer alpha, Integer beta, Integer gamma, boolean hold,
        List<Long> patronIds, Long thrust, Long momentum, Long scaled, Long third, Long norm,
        Long backing, Long quarter, String tier, Long keel,
        Long fathom, Long draft) {

    static PersonView of(Person p, Long averageScaled) {
        return new PersonView(p.getId(), p.getName(), p.getAlpha(), p.getBeta(), p.getGamma(), p.isHold(),
                p.getPatrons().stream().map(Person::getId).sorted().toList(), thrust(p), momentum(p),
                scaled(p), third(p), norm(p, averageScaled), backing(p),
                quarter(p), tier(p), keel(p), fathom(p), draft(p));
    }

    /** The average scaled across the people, skipping n/a; null when nobody has one. */
    static Long averageScaled(List<Person> people) {
        List<Long> values = people.stream().map(PersonView::scaled).filter(v -> v != null).toList();
        if (values.isEmpty()) {
            return null;
        }
        long sum = values.stream().mapToLong(Long::longValue).sum();
        return SheetMath.divide(sum, values.size());
    }

    private static Long norm(Person p, Long averageScaled) {
        Long scaled = scaled(p);
        return scaled == null || averageScaled == null ? null : scaled - averageScaled;
    }

    private static Long backing(Person p) {
        if (momentum(p) == null) {
            return null;
        }
        return p.getPatrons().stream().map(PersonView::momentum).filter(m -> m != null)
                .mapToLong(Long::longValue).sum();
    }

    private static Long thrust(Person p) {
        if (p.getAlpha() == null || p.getBeta() == null) {
            return null;
        }
        return (long) p.getAlpha() * p.getBeta();
    }

    private static Long momentum(Person p) {
        Long thrust = thrust(p);
        if (thrust == null || p.getGamma() == null) {
            return null;
        }
        return thrust + 3L * ((long) p.getGamma() - p.getAlpha());
    }

    private static Long scaled(Person p) {
        Long momentum = momentum(p);
        return momentum == null ? null : momentum * 2L;
    }

    private static Long third(Person p) {
        Long scaled = scaled(p);
        return scaled == null ? null : SheetMath.divide(scaled, 3L);
    }

    private static Long quarter(Person p) {
        Long scaled = scaled(p);
        return scaled == null ? null : SheetMath.divide(scaled, 4L);
    }

    private static Long keel(Person p) {
        Long momentum = momentum(p);
        return momentum == null ? null : scaled(p) + momentum;
    }

    private static Long fathom(Person p) {
        Long keel = keel(p);
        return keel == null ? null : keel + momentum(p);
    }

    private static Long draft(Person p) {
        Long keel = keel(p);
        return keel == null ? null : keel + thrust(p);
    }

    private static String tier(Person p) {
        Long scaled = scaled(p);
        if (scaled == null) {
            return null;
        }
        if (scaled < 0) {
            return "SINK";
        }
        return scaled < 200 ? "STEADY" : "SURGE";
    }
}
import { Component, computed, inject } from '@angular/core';
import { toSignal } from '@angular/core/rxjs-interop';
import { PeopleService } from './people.service';

// Every person on the sheet, one row each.
@Component({
  selector: 'app-people-list',
  template: `
    @if (people(); as list) {
      @if (list.length === 0) {
        <p data-testid="home-empty">Nothing here yet.</p>
      } @else {
        <table data-testid="people-table">
          <caption>People</caption>
          <thead>
            <tr>
              <th scope="col">Name</th>
              <th scope="col">Alpha</th>
              <th scope="col">Beta</th>
              <th scope="col">Gamma</th>
              <th scope="col">On hold</th>
              <th scope="col">Patrons</th>
              <th scope="col">Thrust</th>
              <th scope="col">Momentum</th>
              <th scope="col">Scaled</th>
              <th scope="col">Third</th>
              <th scope="col">Norm</th>
              <th scope="col">Backing</th>
              <th scope="col">Quarter</th>
              <th scope="col">Tier</th>
              <th scope="col">Keel</th>
              <th scope="col">Fathom</th>
              <th scope="col">Draft</th>
            </tr>
          </thead>
          <tbody>
            @for (p of list; track p.id) {
              <tr [attr.data-testid]="'person-row-' + p.id">
                <th scope="row" [attr.data-testid]="'person-name-' + p.id">{{ p.name }}</th>
                <td [attr.data-testid]="'person-alpha-' + p.id">{{ p.alpha ?? '' }}</td>
                <td [attr.data-testid]="'person-beta-' + p.id">{{ p.beta ?? '' }}</td>
                <td [attr.data-testid]="'person-gamma-' + p.id">{{ p.gamma ?? '' }}</td>
                <td [attr.data-testid]="'person-hold-' + p.id">{{ p.hold ? 'Yes' : 'No' }}</td>
                <td [attr.data-testid]="'person-patrons-' + p.id">{{ patronNames(p.patronIds) }}</td>
                <td data-testid="concept-thrust">{{ p.thrust ?? 'n/a' }}</td>
                <td data-testid="concept-momentum">{{ p.momentum ?? 'n/a' }}</td>
                <td data-testid="concept-scaled">{{ p.scaled ?? 'n/a' }}</td>
                <td data-testid="concept-third">{{ p.third ?? 'n/a' }}</td>
                <td data-testid="concept-norm">{{ p.norm ?? 'n/a' }}</td>
                <td data-testid="concept-backing">{{ p.backing ?? 'n/a' }}</td>
                <td data-testid="concept-quarter">{{ p.quarter ?? 'n/a' }}</td>
                <td data-testid="concept-tier">{{ p.tier ?? 'n/a' }}</td>
                <td data-testid="concept-keel">{{ p.keel ?? 'n/a' }}</td>
                <td data-testid="concept-fathom">{{ p.fathom ?? 'n/a' }}</td>
                <td data-testid="concept-draft">{{ p.draft ?? 'n/a' }}</td>
              </tr>
            }
          </tbody>
          <tfoot>
            <tr>
              <th scope="row" colspan="6">Thrust total</th>
              <td data-testid="rollup-thrust-total">{{ thrustTotal() }}</td>
              <td colspan="7"></td>
              <td colspan="3"></td>
            </tr>
            <tr>
              <th scope="row" colspan="14">Keel total</th>
              <td data-testid="rollup-keel-total">{{ keelTotal() }}</td>
              <td colspan="2"></td>
            </tr>
          </tfoot>
        </table>
      }
    }
  `,
})
export class PeopleList {
  protected readonly people = toSignal(inject(PeopleService).list());

  private readonly names = computed(
    () => new Map((this.people() ?? []).map((p) => [p.id, p.name] as const)),
  );

  // Everyone's thrust added up, skipping the people for whom it is n/a.
  protected readonly thrustTotal = computed(() =>
    trimmedTotal((this.people() ?? []).map((p) => p.thrust)),
  );

  // Everyone's keel added up, trimmed like every sheet total.
  protected readonly keelTotal = computed(() =>
    trimmedTotal((this.people() ?? []).map((p) => p.keel)),
  );

  protected patronNames(ids: number[]): string {
    const names = this.names();
    return ids.map((id) => names.get(id) ?? String(id)).join(', ');
  }
}

// A sheet-wide total: the contributions (n/a ones skipped) added up, leaving out one highest and
// one lowest whenever at least two people contribute. Every sheet total goes through this.
export function trimmedTotal(values: (number | null)[]): number {
  const contributions = values.filter((v): v is number => v !== null);
  const sum = contributions.reduce((total, v) => total + v, 0);
  if (contributions.length < 2) {
    return sum;
  }
  return sum - Math.max(...contributions) - Math.min(...contributions);
}
